        || !Run(true, false, 3, -1, -1, "pause;ASIDE;unpause;")
        || !Run(true, false, -1, 5, -1, "pause;ATTACKED;unpause;attack;")
        || !Run(true, false, -1, 5, 14, "")
        || !Run(true, false, -1, 5, 3, "pause;ATTACKED;unpause;attack;")
